import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

import * as esbuild from "esbuild";

const root = fileURLToPath(new URL("..", import.meta.url));
const outputPath = path.join(
  root,
  "test-artifacts",
  "perf-profile",
  "p7-profile.user.js",
);
const metadata = (
  await readFile(path.join(root, "src", "userscript.meta.js"), "utf8")
).trimEnd();
const result = await esbuild.build({
  absWorkingDir: root,
  entryPoints: ["src/main.ts"],
  outfile: outputPath,
  bundle: true,
  banner: {
    js: `${metadata}\n\n// Generated by npm run build. Edit files under src/ instead.`,
  },
  charset: "utf8",
  format: "iife",
  legalComments: "inline",
  logLevel: "silent",
  platform: "browser",
  target: ["esnext"],
  define: {
    "globalThis.__EA_TEST_SURFACE_ENABLED__": "false",
    __EA_TEST_SURFACE_ENABLED__: "false",
    __EA_RESEARCH_CONDITION_GATE_ENABLED__: "false",
  },
  minifySyntax: true,
  treeShaking: true,
  sourcemap: "external",
  sourcesContent: true,
});
const [production, mapped] = await Promise.all([
  readFile(path.join(root, "evolve_automation.user.js"), "utf8"),
  readFile(outputPath, "utf8"),
]);
const withoutMapComment = mapped.replace(
  /\n\/\/# sourceMappingURL=.*\r?\n?$/u,
  "\n",
);
if (withoutMapComment !== production)
  throw new Error(
    "Source-mapped profiling bundle differs from the production bundle body",
  );
console.log(
  JSON.stringify({
    outputPath,
    mapPath: `${outputPath}.map`,
    outputFiles: result.outputFiles?.length ?? 0,
    productionBodyMatches: true,
  }),
);
